package dev.zomboid.gore;
public class EffectsChecks14{
 static int checks;static void ok(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
 public record V(double x,double y,double z){}public record Transform(Object position){}
 public static class Block{public boolean isSolidRender(Object world,Object pos){return false;}}
 public static class World{public int particles,sounds;public double vx,vy;public boolean hasChunkAt(Object p){return true;}public Object getBlockState(Object p){return new Block();}public void addParticle(Object type,double x,double y,double z,double dx,double dy,double dz){particles++;vx=dx;vy=dy;}public void playSound(Object player,double x,double y,double z,Object sound,Object source,float volume,float pitch){sounds++;}public void playLocalSound(double x,double y,double z,Object sound,Object source,float volume,float pitch,boolean delay){sounds++;}}
 public static void main(String[]args){World world=new World();Artery14.frame(world,100);Blood12.particle=new Object();Blood12.used=0;for(int i=0;i<20;i++)Artery14.pulse(world,0,1,0,1,0,3);ok(world.particles==12&&Blood12.used==12,"arterial spray has a shared twelve-particle cap per tick");ok(world.vx>.15&&world.vy<.14,"pressure is directional rather than a vertical fountain");Artery14.frame(world,101);Blood12.used=48;int old=world.particles;Artery14.pulse(world,0,1,0,1,0,3);ok(world.particles==old,"arterial blood obeys the existing global blood budget");Blood12.used=0;Artery14.deadEmit(world,0,0,0,true,10);ok(world.particles==old+1&&world.vy==.045,"dead wounds drain one low-speed drop without head fountain");
 var s=new Artery14.State();Artery14.frame(world,200);Artery14.sound(world,0,0,0,s,200,true);Artery14.sound(world,0,0,0,s,210,true);ok(world.sounds==1,"arterial sound is not restarted every tick");Artery14.sound(world,0,0,0,new Artery14.State(),200,true);Artery14.sound(world,0,0,0,new Artery14.State(),200,true);ok(world.sounds==2,"global sound burst limited to two starts per tick");Artery14.frame(world,230);Artery14.sound(world,0,0,0,s,230,true);ok(world.sounds==3,"sustained injury can produce a later bounded pulse");
 World server=new World();Object hurt=new Object();Artery14.serverSound(server,hurt,1,2,3,500);ok(server.sounds==1,"server sends artery sound immediately even if the impact kills its entity");Artery14.serverSound(server,hurt,1,2,3,501);ok(server.sounds==1,"repeated pellets cannot restart initial artery sound immediately");
 int result=CorpseLight14.point(new V(1,2,3),0xF00000);ok((result&0xF00000)==0xF00000&&((result>>4)&15)==6,"corpse bridge preserves sky light and gets block light from flashlight API");Object sample=net.flashlight.battery.EntityLight14.last;ok(sample instanceof CorpseLight14.Point,"lighting samples a physical segment rather than a fake living entity");var box=(net.minecraft.world.phys.AABB)((CorpseLight14.Point)sample).getBoundingBox();ok(box.getCenter().x()==1&&box.getCenter().y()==2,"sample box centered at physical limb position");net.minecraft.client.Minecraft.INSTANCE.level=world;CorpseLight14.transform(new Transform(new V(-1,2,3)),0);ok(net.flashlight.battery.EntityLight14.lastOriginal==32,"shadowed segment gets its own native ambient light");CorpseLight14.transform(new Transform(new V(1,2,3)),0);ok(net.flashlight.battery.EntityLight14.lastOriginal==160,"illuminated segment samples its own ambient position");for(int i=0;i<200;i++)CorpseLight14.point(new V(i,0,0),0);ok(CorpseLight14.POINTS.size()<=64,"corpse sample cache is bounded");System.out.println("ARTERIAL_AUDIO_PARTICLE_BUDGET_AND_SEGMENT_LIGHT_CHECKS="+checks);}
}
